# ordered path rewrites applied by debian-install; first match wins
# regex<TAB>replacement   or   DROP<TAB>regex
# %{var} expands at build time: libdir perl_vendorlib perl_vendorarch python3_sitepkgs rb_vendorlibdir rb_vendorarchdir
DROP	^/usr/share/lintian/
DROP	^/usr/share/bug/
DROP	^/usr/share/doc-base/
DROP	^/DEBIAN/
DROP	\.la$
DROP	^/usr/share/doc/[^/]+/changelog\.Debian
DROP	^/usr/share/doc/[^/]+/NEWS\.Debian
^/usr/lib/x86_64-linux-gnu/perl5/5\.[0-9.]+/	%{perl_vendorarch}/
^/usr/lib/x86_64-linux-gnu/perl-base/	%{perl_vendorarch}/
^/usr/share/perl5/	%{perl_vendorlib}/
^/usr/lib/python3/dist-packages/	%{python3_sitepkgs}/
^/usr/lib/x86_64-linux-gnu/ruby/vendor_ruby/[0-9.]+/	%{rb_vendorarchdir}/
^/usr/lib/ruby/vendor_ruby/	%{rb_vendorlibdir}/
^/usr/share/nodejs/	/usr/lib/node_modules/
^/usr/lib/x86_64-linux-gnu/	%{libdir}/
^/usr/share/doc/([^/]+)	/usr/share/doc/packages/$1
^/(bin|sbin|lib)/	/usr/$1/
